package com.optarena.app;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class UserLeakHiddenTest {

    @Autowired
    private MockMvc mvc;

    @Test
    void createDoesNotLeakHash() throws Exception {
        // NOTE: the controller is a shared singleton across test methods, so
        // ids are not asserted to specific values (order-independent).
        mvc.perform(post("/users").contentType("application/json")
                .content("{\"username\": \"ada\", \"password\": \"s3cret\"}"))
           .andExpect(status().isCreated())
           .andExpect(jsonPath("$.id").isNumber())
           .andExpect(jsonPath("$.username").value("ada"))
           .andExpect(jsonPath("$.passwordHash").doesNotExist())
           .andExpect(jsonPath("$.password").doesNotExist());
    }

    @Test
    void getDoesNotLeakHash() throws Exception {
        String resp = mvc.perform(post("/users").contentType("application/json")
                .content("{\"username\": \"bob\", \"password\": \"hunter2\"}"))
           .andExpect(status().isCreated())
           .andReturn().getResponse().getContentAsString();
        int id = com.jayway.jsonpath.JsonPath.read(resp, "$.id");
        mvc.perform(get("/users/" + id))
           .andExpect(status().isOk())
           .andExpect(jsonPath("$.username").value("bob"))
           .andExpect(jsonPath("$.passwordHash").doesNotExist());
    }
}

